from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class XnlinkParamsGenerator(ManagedObject):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.xnlink_ent = self.enb_ent_config['xnlink'][self.mo_num]

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        ip_addr = self.xnlink_ent['ip_addr']
        self.set_parameter('cPlaneIpAddr', ip_addr)
        self.set_parameter('cPlaneIpAddrCtrl', 'gnbControlled')
